<?php use app\components\Ui; use yii\helpers\Html; use Lunixi\Sdk\Commerce\Money; ?><h1><?= Ui::escape(Ui::text('orders')) ?></h1><?php foreach ($orders as $order): ?><article><h2>#<?= (int) $order['id'] ?></h2><p><?= Ui::escape(Money::decimal((int) $order['amount'],Money::exponent($order['currency']))) ?> <?= Ui::escape($order['currency']) ?> · <?= Ui::escape(Ui::text('state_'.$order['state'])) ?></p><?php if ($order['state'] === 'pending'): ?><?= Html::beginForm(['/payment/checkout','id'=>(int) $order['id']],'post') ?><button type="submit"><?= Ui::escape(Ui::text('pay')) ?></button><?= Html::endForm() ?><?php endif ?></article><?php endforeach ?><?= Html::beginForm(['/site/logout'],'post') ?><button type="submit"><?= Ui::escape(Ui::text('logout')) ?></button><?= Html::endForm() ?>
